<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>Vowel Counter</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #ffffff; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
  </style>
</head>
<body>
  <h2 id="title">Vowel Counter</h2>
  <input id="s" type="text" placeholder="Type a sentence">
  <button id="go">Count</button>
  <h3 id="out"></h3>
  <script>
    var c, txt, k;

    document.getElementById("go").addEventListener('click', function () {
      c = 0;
      txt = document.getElementById("s").value.toLowerCase();
      var k_end = txt.length;
      var k_inc = 1;
      if (1 > k_end) {
        k_inc = -k_inc;
      }
      for (k = 1; k_inc >= 0 ? k <= k_end : k >= k_end; k += k_inc) {
        if ('aeiou'.indexOf(txt.charAt((k - 1))) + 1 > 0) {
          c = (typeof c === 'number' ? c : 0) + 1;
        }
      }
      document.getElementById("out").textContent = 'Vowels: ' + String(c);
    });
  </script>
</body>
</html>

```

