  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #fce7f3; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
  </style>
</head>
<body>
  <h2 id="title">오늘의 운세</h2>
  <h1 id="out">🔮</h1>
  <button id="go">뽑기</button>
  <p id="txt"></p>
  <script>
    var r;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("go").addEventListener('click', function () {
      r = mathRandomInt(1, 3);
      if (r == 1) {
        document.getElementById("out").textContent = '🍀';
        document.getElementById("txt").textContent = '대박 행운!';
      } else if (r == 2) {
        document.getElementById("out").textContent = '🙂';
        document.getElementById("txt").textContent = '평범한 하루';
      } else {
        document.getElementById("out").textContent = '☔';
        document.getElementById("txt").textContent = '우산을 챙겨요';
      }
    });
  </script>
</body>
</html>
