<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>사칙연산 계산기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #ffedd5; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    input { font-size: 18px; padding: 8px; margin: 4px; }
  </style>
</head>
<body>
  <h1>사칙연산 계산기</h1>
  <input id="a" type="number" placeholder="첫 번째 수">
  <input id="b" type="number" placeholder="두 번째 수">
  <div>
    <button id="add">+</button>
    <button id="sub">-</button>
    <button id="mul">×</button>
    <button id="div">÷</button>
  </div>
  <h2 id="result">결과: </h2>
  <script>
    const a = document.getElementById('a');
    const b = document.getElementById('b');
    const result = document.getElementById('result');
    function show(value) {
      result.textContent = '결과: ' + value;
    }
    document.getElementById('add').addEventListener('click', function () {
      const x = Number(a.value);
      const y = Number(b.value);
      show(x + y);
    });
    document.getElementById('sub').addEventListener('click', function () {
      const x = Number(a.value);
      const y = Number(b.value);
      show(x - y);
    });
