    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var odd, even, n;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("goBtn").addEventListener('click', function () {
      odd = 0;
      even = 0;
      document.getElementById("nums").textContent = '';
      for (var count = 0; count < 20; count++) {
        n = mathRandomInt(1, 100);
        __add("nums", String(n) + ' ');
        if (n % 2 === 0) {
          even = (typeof even === 'number' ? even : 0) + 1;
        } else {
          odd = (typeof odd === 'number' ? odd : 0) + 1;
        }
      }
      document.getElementById("out").textContent = ['홀수 ',odd,'개 · 짝수 ',even,'개'].join('');
    });
  </script>
