      if (__dist(x, y, sx, sy) < 25) {
        score = (typeof score === 'number' ? score : 0) + 1;
        sx = mathRandomInt(20, 300);
        sy = mathRandomInt(20, 200);
        __beep(261.63, 0.08);
        document.getElementById("점수판").textContent = '점수: ' + String(score);
      }
    }, 30));
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowDown") {
        e.preventDefault();
        y = (typeof y === 'number' ? y : 0) + 10;
      }
    });
    document.getElementById("그림판1").style.touchAction = 'none';
    document.getElementById("그림판1").addEventListener('pointermove', function (e) {
      if (!e.buttons) return;
      __pos(e, this);
      x = __mx;
      y = __my;
