    document.getElementById("f4").addEventListener('click', function () {
      go(4);
    });
    document.getElementById("f8").addEventListener('click', function () {
      go(8);
    });
    __timers.push(setInterval(function () {
      if (floor < goal) {
        floor = (typeof floor === 'number' ? floor : 0) + 1;
        document.getElementById("msg").textContent = '올라가는 중...';
      } else if (floor > goal) {
