<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>영어 단어 맞히기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #f0fdf4; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    .key { width: 46px; padding: 10px 0; margin: 3px; }
    #word { font-size: 40px; letter-spacing: 12px; font-family: monospace; margin: 12px; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🔤 영어 단어 맞히기</h1>
  <p>힌트: <span id="hint"></span> · 남은 기회: <span id="left">6</span> <span id="hearts"></span></p>
  <div id="word"></div>
  <div id="keys"></div>
  <p id="msg"></p>
  <button id="restart">새 단어</button>
  <script>
    const WORDS = [
      { word: 'APPLE', hint: '사과' }, { word: 'TIGER', hint: '호랑이' }, { word: 'SCHOOL', hint: '학교' },
      { word: 'PENCIL', hint: '연필' }, { word: 'RAINBOW', hint: '무지개' }, { word: 'ROCKET', hint: '로켓' },
      { word: 'BANANA', hint: '바나나' }, { word: 'FRIEND', hint: '친구' }
    ];
    const MAX_WRONG = 6;
    const keysEl = document.getElementById('keys');
    const msg = document.getElementById('msg');
    let answer = '';
    let guessed = [];
    let wrong = 0;
    let running = false;

    function show() {
      document.getElementById('word').textContent = answer.split('').map(function (ch) {
        return guessed.includes(ch) ? ch : '_';
      }).join('');
      document.getElementById('left').textContent = MAX_WRONG - wrong;
      document.getElementById('hearts').textContent = '❤️'.repeat(MAX_WRONG - wrong);
    }

    function guess(letter, btn) {
      if (!running || guessed.includes(letter)) return;
      guessed.push(letter);
      btn.disabled = true;
      if (!answer.includes(letter)) wrong += 1;
      show();
      if (answer.split('').every(function (ch) { return guessed.includes(ch); })) {
        running = false;
        msg.textContent = '🎉 정답! ' + answer;
      } else if (wrong >= MAX_WRONG) {
        running = false;
        msg.textContent = '💥 게임 오버! 정답은 ' + answer;
      }
    }

    function newGame() {
      const pick = WORDS[Math.floor(Math.random() * WORDS.length)];
      answer = pick.word;
      document.getElementById('hint').textContent = pick.hint;
      guessed = [];
      wrong = 0;
      running = true;
      msg.textContent = '';
      keysEl.innerHTML = '';
      'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').forEach(function (letter) {
        const b = document.createElement('button');
        b.className = 'key';
        b.textContent = letter;
        b.addEventListener('click', function () { guess(letter, b); });
        keysEl.appendChild(b);
      });
      show();
    }

    // 키보드로 알파벳을 눌러도 돼요
    document.addEventListener('keydown', function (e) {
      const letter = e.key.toUpperCase();
      if (!/^[A-Z]$/.test(letter)) return;
      const btn = Array.from(keysEl.children).find(function (b) { return b.textContent === letter; });
      if (btn) guess(letter, btn);
    });
    document.getElementById('restart').addEventListener('click', newGame);
    newGame();
  </script>
</body>
</html>
```

