        var k_inc = 1;
        if (2 > k_end) {
          k_inc = -k_inc;
        }
        for (k = 2; k_inc >= 0 ? k <= k_end : k >= k_end; k += k_inc) {
          if (mathIsPrime(k)) {
            c = (typeof c === 'number' ? c : 0) + 1;
            __add("list", String(k) + ' ');
          }
        }
        document.getElementById("count").textContent = 'How many primes: ' + String(c);
      }
    });
