      var x = Math.max(0, Math.min(parseFloat(s.left) || 0, d.clientWidth - el.offsetWidth));
      var y = Math.max(0, Math.min(parseFloat(s.top) || 0, d.clientHeight - el.offsetHeight));
      s.left = x + 'px';
      s.top = y + 'px';
    }
    var __timers = [];

    var t;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    __timers.push(setInterval(function () {
      __nudge("foe", 0, 9);
      if (__where("foe", "y") > 380) {
        __move("foe", mathRandomInt(20, 260), 0);
      }
      if (__hit("foe", "me")) {
        __timers.forEach(clearInterval);
        document.getElementById("hint").textContent = '부딪혔어요! 게임 끝';
      }
    }, 50));
    __timers.push(setInterval(function () {
      t = (typeof t === 'number' ? t : 0) + 1;
      document.getElementById("tm").textContent = '버틴 시간: ' + String(t);
    }, 1000));
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        __nudge("me", -25, 0);
        __stay("me");
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        __nudge("me", 25, 0);
        __stay("me");
      }
    });

