  </style>
</head>
<body>
  <h2 id="title">Math Sprint</h2>
  <h1 id="problem">?</h1>
  <input id="ans" type="number" placeholder="Answer + Enter">
  <div id="info" class="box row">
    <p id="score">Correct: 0</p>
    <p id="time">Time: 30</p>
  </div>
  <button id="go">Start</button>
  <p id="best">Best: 0</p>
  <script>
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var a, playing, score, b, hi, left;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function newProblem() {
      a = mathRandomInt(1, 20);
      b = mathRandomInt(1, 20);
      document.getElementById("problem").textContent = [a,' + ',b,' = ?'].join('');
      document.getElementById("ans").value = '';
    }

    document.getElementById("go").addEventListener('click', function () {
      score = 0;
      left = 30;
      playing = true;
      document.getElementById("score").textContent = 'Correct: ' + String(0);
      newProblem();
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        if (playing) {
          if ((parseFloat(document.getElementById("ans").value) || 0) == a + b) {
            score = (typeof score === 'number' ? score : 0) + 1;
            document.getElementById("score").textContent = 'Correct: ' + String(score);
            __beep(329.63, 0.08);
          }
          newProblem();
        }
      }
    });
    __timers.push(setInterval(function () {
      if (playing) {
        left = (typeof left === 'number' ? left : 0) + -1;
        document.getElementById("time").textContent = 'Time: ' + String(left);
        if (left <= 0) {
          playing = false;
          document.getElementById("problem").textContent = 'Time\'s up! Correct: ' + String(score);
          if (score > hi) {
            hi = score;
            document.getElementById("best").textContent = 'Best: ' + String(hi);
          }
        }
      }
    }, 1000));

    playing = false;
    hi = 0;
  </script>
</body>
</html>
