      if (n > 0) {
        var k_inc = 1;
        if (1 > n) {
          k_inc = -k_inc;
        }
        for (k = 1; k_inc >= 0 ? k <= n : k >= n; k += k_inc) {
          if (n % k == 0) {
            __add("numList", k);
          }
        }
      }
    });
  </script>
