        __show("quizBox", "hide");
        document.getElementById("final").textContent = ['끝! 점수: ',score,' / ',qs.length].join('');
      } else {
        document.getElementById("question").textContent = qs[(i - 1)];
        right = answers[(i - 1)];
        document.getElementById("answer").value = '';
      }
    }

    document.getElementById("check").addEventListener('click', function () {
