<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>순서 기억하기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #1f2937; color: #f9fafb; padding: 24px; }
    #pad { display: grid; grid-template-columns: repeat(2, 120px); gap: 12px; justify-content: center; margin: 16px auto; }
    .color { width: 120px; height: 120px; border: none; border-radius: 20px; opacity: 0.45; cursor: pointer; }
    .color.lit { opacity: 1; box-shadow: 0 0 24px white; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🧠 순서 기억하기</h1>
  <p>단계: <span id="level">0</span></p>
  <div id="pad">
    <button class="color" style="background: #ef4444"></button>
    <button class="color" style="background: #3b82f6"></button>
    <button class="color" style="background: #22c55e"></button>
    <button class="color" style="background: #eab308"></button>
  </div>
  <p id="msg">시작을 누르면 불빛 순서를 보여 줘요</p>
  <button id="start">시작</button>
  <script>
    const pads = document.querySelectorAll('.color');
    const notes = [330, 392, 494, 587];
    const msg = document.getElementById('msg');
    let audio = null;
    let sequence = [];
    let inputIndex = 0;
    let accepting = false;   // 내 차례일 때만 true
    let running = false;
    let timeouts = [];

    function sound(i) {
      if (!audio) audio = new AudioContext();
      const osc = audio.createOscillator();
      const gain = audio.createGain();
      osc.frequency.value = notes[i];
      gain.gain.value = 0.15;
      osc.connect(gain);
      gain.connect(audio.destination);
      osc.start();
      osc.stop(audio.currentTime + 0.25);
    }

    function flash(i) {
      pads[i].classList.add('lit');
      sound(i);
      timeouts.push(setTimeout(function () { pads[i].classList.remove('lit'); }, 300));
    }

    function nextRound() {
      sequence.push(Math.floor(Math.random() * 4));
      document.getElementById('level').textContent = sequence.length;
      inputIndex = 0;
      accepting = false;
      msg.textContent = '잘 보세요 👀';
      sequence.forEach(function (c, k) {
        timeouts.push(setTimeout(function () { flash(c); }, 600 + k * 500));
      });
      timeouts.push(setTimeout(function () {
        accepting = true;
        msg.textContent = '내 차례! 순서대로 눌러요';
      }, 600 + sequence.length * 500));
    }

    function startGame() {
      timeouts.forEach(clearTimeout); // 보여 주던 순서도 멈춰요
      timeouts = [];
      pads.forEach(function (p) { p.classList.remove('lit'); });
      sequence = [];
      running = true;
      document.getElementById('start').textContent = '다시 시작';
      nextRound();
    }

    pads.forEach(function (pad, i) {
      pad.addEventListener('click', function () {
        if (!running || !accepting) return;
        flash(i);
        if (i !== sequence[inputIndex]) {
          running = false;
          accepting = false;
          msg.textContent = '💥 게임 오버! ' + (sequence.length - 1) + '단계까지 성공';
          return;
        }
        inputIndex += 1;
        if (inputIndex === sequence.length) {
          accepting = false;
          msg.textContent = '⭕ 좋아요!';
          timeouts.push(setTimeout(nextRound, 700));
        }
      });
    });
    document.getElementById('start').addEventListener('click', startGame);
  </script>
</body>
</html>
