  </style>
</head>
<body>
  <h1>🔢 업다운 게임</h1>
  <p>1부터 50 사이 숫자를 7번 안에 맞혀 보세요!</p>
  <input id="guess" type="number" min="1" max="50">
  <button id="check">확인</button>
  <p id="result"></p>
  <p>남은 기회: <span id="left">7</span>번</p>
  <p id="history"></p>
  <button id="restart">다시 시작</button>
  <script>
    const MAX_TRIES = 7;
    let answer = 0;
    let tries = 0;
    let running = false;
    const guess = document.getElementById('guess');
    const result = document.getElementById('result');
    const checkBtn = document.getElementById('check');

    function startGame() {
      answer = Math.floor(Math.random() * 50) + 1;
      tries = 0;
      running = true;
      checkBtn.disabled = false;
      result.textContent = '';
      document.getElementById('history').textContent = '';
      document.getElementById('left').textContent = MAX_TRIES;
      guess.value = '';
    }

    function check() {
      if (!running) return;
      const n = Number(guess.value);
      if (!Number.isInteger(n) || n < 1 || n > 50) {
        result.textContent = '1부터 50 사이 숫자를 써 주세요';
        return; // 잘못 쓴 건 기회를 쓰지 않아요
      }
      tries += 1;
      document.getElementById('left').textContent = MAX_TRIES - tries;
      document.getElementById('history').textContent += n + ' ';
      if (n === answer) {
        result.textContent = '🎉 정답! ' + tries + '번 만에 맞혔어요';
        running = false;
        checkBtn.disabled = true;
      } else if (tries >= MAX_TRIES) {
        result.textContent = '💥 게임 오버! 정답은 ' + answer + '였어요';
        running = false;
        checkBtn.disabled = true;
      } else if (n < answer) {
        result.textContent = '⬆️ 업! 더 큰 수예요';
      } else {
        result.textContent = '⬇️ 다운! 더 작은 수예요';
      }
      guess.value = '';
      guess.focus();
    }

    checkBtn.addEventListener('click', check);
    guess.addEventListener('keydown', function (e) {
      if (e.key === 'Enter') check();
    });
    document.getElementById('restart').addEventListener('click', startGame);
    startGame();
  </script>
</body>
</html>
