  <script>
    function $(name) {
      if (name && name.nodeType) return name;
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" element does not exist');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    function __beep(freq, sec) {
      __snd();
      __tone(freq, __audio.currentTime, sec, 'sine', 0.2);
    }
    var __audio, __sndBus = null;
    function __snd() {
      if (!__audio) {
        __audio = new (window.AudioContext || window.webkitAudioContext)();
        ['pointerdown', 'keydown'].forEach(function (k) { document.addEventListener(k, function () { if (__audio.state === 'suspended') __audio.resume(); }); });
      }
      if (__audio.state === 'suspended') __audio.resume();
      if (!__sndBus) { __sndBus = __audio.createGain(); __sndBus.connect(__audio.destination); }
      return __sndBus;
    }
    function __tone(freq, t, sec, type, vol, to, hold) {
      var o = __audio.createOscillator(), g = __audio.createGain();
      o.type = type;
      o.frequency.setValueAtTime(freq, t);
      if (to) o.frequency.exponentialRampToValueAtTime(to, t + sec);
      g.gain.setValueAtTime(vol, t);
      if (hold) g.gain.setValueAtTime(vol, t + sec * hold);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.connect(g); g.connect(__snd());
      o.start(t); o.stop(t + sec + 0.02);
    }
