<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>피아노</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #18181b; color: #fafafa; padding: 24px; }
    #piano { display: flex; justify-content: center; margin: 20px auto; }
    .key { width: 56px; height: 200px; margin: 0 2px; border: 1px solid #333; border-radius: 0 0 8px 8px; background: white;
      color: #333; font-size: 16px; display: flex; flex-direction: column; justify-content: flex-end; padding-bottom: 10px; cursor: pointer; }
    .key.on { background: #fde047; }
    #now { font-size: 28px; min-height: 36px; }
  </style>
</head>
<body>
  <h1>🎹 피아노</h1>
  <p>건반을 클릭하거나 키보드 A S D F G H J K 를 눌러요</p>
  <div id="piano"></div>
  <p id="now"></p>
  <script>
    const NOTES = [
      { name: '도', key: 'a', freq: 261.63 }, { name: '레', key: 's', freq: 293.66 },
      { name: '미', key: 'd', freq: 329.63 }, { name: '파', key: 'f', freq: 349.23 },
      { name: '솔', key: 'g', freq: 392.0 }, { name: '라', key: 'h', freq: 440.0 },
      { name: '시', key: 'j', freq: 493.88 }, { name: '높은 도', key: 'k', freq: 523.25 }
    ];
    const keyEls = [];
    let audio = null;
    let played = 0;

    function playNote(i) {
      if (!audio) audio = new AudioContext(); // 처음 누를 때 만들어요
      const osc = audio.createOscillator();
      const gain = audio.createGain();
      osc.type = 'triangle';
      osc.frequency.value = NOTES[i].freq;
      gain.gain.setValueAtTime(0.3, audio.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, audio.currentTime + 0.8); // 점점 작아지게
      osc.connect(gain);
      gain.connect(audio.destination);
      osc.start();
      osc.stop(audio.currentTime + 0.8);
      played += 1;
      document.getElementById('now').textContent = '🎵 ' + NOTES[i].name;
      keyEls[i].classList.add('on');
      setTimeout(function () { keyEls[i].classList.remove('on'); }, 150);
    }

    NOTES.forEach(function (note, i) {
      const el = document.createElement('div');
      el.className = 'key';
      el.innerHTML = '<b>' + note.name + '</b><small>' + note.key.toUpperCase() + '</small>';
      el.addEventListener('mousedown', function () { playNote(i); });
      document.getElementById('piano').appendChild(el);
      keyEls.push(el);
    });

    document.addEventListener('keydown', function (e) {
      if (e.repeat) return; // 꾹 누르고 있을 때 계속 울리지 않게
      const i = NOTES.findIndex(function (n) { return n.key === e.key.toLowerCase(); });
      if (i !== -1) playNote(i);
    });
  </script>
</body>
</html>
