    function logMood(m) {
      __add("log", [m,' ',pad(new Date().getHours()),':',pad(new Date().getMinutes())].join(''));
    }

    document.getElementById("happyBtn").addEventListener('click', function () {
      logMood('😊');
    });
    document.getElementById("okBtn").addEventListener('click', function () {
      logMood('😐');
