  <h1 id="title1">약수 찾기</h1>
  <input id="numBox" type="number" placeholder="자연수">
  <button id="findBtn">약수 구하기</button>
  <ul id="divList"></ul>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var n, cnt, i;

    document.getElementById("findBtn").addEventListener('click', function () {
      document.getElementById("divList").textContent = '';
      n = (parseFloat(document.getElementById("numBox").value) || 0);
      cnt = 0;
      var i_inc = 1;
      if (1 > n) {
        i_inc = -i_inc;
      }
      for (i = 1; i_inc >= 0 ? i <= n : i >= n; i += i_inc) {
        if (n % i == 0) {
          __add("divList", i);
          cnt = (typeof cnt === 'number' ? cnt : 0) + 1;
        }
      }
    });
  </script>
</body>
