    }
    var __mem = {};
    function __save(k, v) {
      k = 'ffb:' + k;
      __mem[k] = v;
      try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {}
    }
    function __load(k, d) {
      k = 'ffb:' + k;
      try {
