      if (mode === 'stop') {
        delete __fol[name];
        var e = document.getElementById(name);
        if (e) e.style.pointerEvents = '';
        return;
      }
      $(name);
      __fol[name] = mode;
      document.body.style.touchAction = 'none';
      if (!__folOn) { __folOn = true; __folLoop(); }
    }
    var __timers = [];

    var score;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
