    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #ffffff; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
  </style>
</head>
<body>
  <h1 id="title1">로또 번호 뽑기</h1>
  <h2 id="nums">?</h2>
  <button id="go">뽑기</button>
  <script>
    var picked, r;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    function listsGetSortCompare(type, direction) {
      var compareFuncs = {
        'NUMERIC': function(a, b) {
            return Number(a) - Number(b); },
        'TEXT': function(a, b) {
            return String(a) > String(b) ? 1 : -1; },
        'IGNORE_CASE': function(a, b) {
            return String(a).toLowerCase() > String(b).toLowerCase() ? 1 : -1; },
      };
      var compare = compareFuncs[type];
      return function(a, b) { return compare(a, b) * direction; };
    }

    document.getElementById("go").addEventListener('click', function () {
      picked = [];
      while (picked.length < 6) {
        r = mathRandomInt(1, 45);
        if (picked.indexOf(r) + 1 == 0) {
          picked.push(r);
        }
      }
      document.getElementById("nums").textContent = picked.slice().sort(listsGetSortCompare("NUMERIC", 1));
    });
  </script>
</body>
</html>
