<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>블록 쌓기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #eef2ff; color: #1f2937; padding: 24px; }
    canvas { background: #1e1b4b; border-radius: 8px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    #msg { font-size: 24px; font-weight: bold; min-height: 30px; }
  </style>
</head>
<body>
  <h1>🏗️ 블록 쌓기</h1>
  <p>높이: <span id="score">0</span>층</p>
  <canvas id="game" width="320" height="440"></canvas>
  <p id="msg">스페이스바나 클릭으로 블록을 내려놓아요. 삐져나온 부분은 잘려요!</p>
  <button id="start">시작</button>
  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const BLOCK_H = 20;
    const msg = document.getElementById('msg');
    let stack = [];      // 쌓인 블록 { x, w }
    let moving = null;   // 움직이는 블록 { x, w, dx }
    let score = 0;
    let running = false;
    let timer = null;

    function startGame() {
      clearInterval(timer);
      stack = [{ x: 90, w: 140 }];
      score = 0;
      newBlock();
      running = true;
      msg.textContent = '';
      document.getElementById('score').textContent = 0;
      document.getElementById('start').textContent = '다시 시작';
      timer = setInterval(tick, 16);
    }

    function newBlock() {
      const top = stack[stack.length - 1];
      moving = { x: 0, w: top.w, dx: 2 + score * 0.2 };
    }

    function gameOver() {
      running = false;
      clearInterval(timer);
      timer = null;
      msg.textContent = '💥 게임 오버! ' + score + '층까지 쌓았어요';
      draw();
    }

    function place() {
      if (!running) return;
      const top = stack[stack.length - 1];
      // 겹친 부분만 남겨요
      const left = Math.max(moving.x, top.x);
      const right = Math.min(moving.x + moving.w, top.x + top.w);
      const w = right - left;
      if (w <= 0) {
        gameOver();
        return;
      }
      stack.push({ x: left, w: w });
      score += 1;
      document.getElementById('score').textContent = score;
      newBlock();
    }

    function tick() {
      if (!running) return;
      moving.x += moving.dx;
      if (moving.x < 0 || moving.x + moving.w > W) {
        moving.dx = -moving.dx;
        moving.x = Math.max(0, Math.min(W - moving.w, moving.x));
      }
      draw();
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      // 높이 쌓이면 아래쪽은 화면 밖으로 내려가게
      const shift = Math.max(0, stack.length - 15) * BLOCK_H;
      stack.forEach(function (b, i) {
        ctx.fillStyle = 'hsl(' + (i * 25) % 360 + ', 70%, 60%)';
        ctx.fillRect(b.x, H - (i + 1) * BLOCK_H + shift, b.w, BLOCK_H - 2);
      });
      if (running && moving) {
        ctx.fillStyle = 'white';
        ctx.fillRect(moving.x, H - (stack.length + 1) * BLOCK_H + shift, moving.w, BLOCK_H - 2);
      }
    }

    document.addEventListener('keydown', function (e) {
      if (e.key.startsWith('Arrow') || e.key === ' ') e.preventDefault();
      if (e.key === ' ' && !e.repeat) place();
    });
    canvas.addEventListener('mousedown', place);
    document.getElementById('start').addEventListener('click', startGame);
    stack = [{ x: 90, w: 140 }];
    draw();
  </script>
</body>
</html>
