  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }
    var __timers = [];

    var sec, run;

    __timers.push(setInterval(function () {
      if (run) {
        sec = (typeof sec === 'number' ? sec : 0) + 1;
        document.getElementById("clock").textContent = [Math.floor(sec / 60),'분 ',sec % 60,'초'].join('');
      }
    }, 1000));
    document.getElementById("startBtn").addEventListener('click', function () {
      sec = 0;
      run = true;
    });
    document.getElementById("stopBtn").addEventListener('click', function () {
      if (run) {
        run = false;
        __add("logList", [Math.floor(sec / 60),'분 ',sec % 60,'초'].join(''));
      }
    });

    sec = 0;
    run = false;
  </script>
</body>
