<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>글자색 맞히기</title>
  <style>
    body { font-family: sans-serif; text-align: center; background: #f8fafc; color: #1f2937; padding: 24px; }
    button { font-size: 18px; padding: 10px 18px; margin: 4px; cursor: pointer; }
    .pick { color: white; border: none; border-radius: 10px; min-width: 80px; }
    #word { font-size: 64px; font-weight: bold; margin: 16px; min-height: 80px; }
    #msg { font-size: 22px; font-weight: bold; min-height: 28px; }
  </style>
</head>
<body>
  <h1>🎨 글자색 맞히기</h1>
  <p>글자 뜻 말고 <b>글자 색깔</b>을 고르세요!</p>
  <p>점수: <span id="score">0</span> · 목숨: <span id="lives">3</span> · 남은 시간: <span id="time">30</span>초</p>
  <div id="word">?</div>
  <div id="picks"></div>
  <p id="msg"></p>
  <button id="start">시작</button>
  <script>
    const colors = [
      { name: '빨강', code: '#dc2626' },
      { name: '파랑', code: '#2563eb' },
      { name: '초록', code: '#16a34a' },
      { name: '노랑', code: '#ca8a04' },
      { name: '보라', code: '#9333ea' }
    ];
    let inkIndex = 0;   // 정답(글자 색깔)
    let score = 0;
    let lives = 3;
    let timeLeft = 30;
    let running = false;
    let timer = null;
    const wordEl = document.getElementById('word');
    const msg = document.getElementById('msg');

    colors.forEach(function (c, i) {
      const b = document.createElement('button');
      b.className = 'pick';
      b.textContent = c.name;
      b.style.background = c.code;
      b.addEventListener('click', function () { answer(i); });
      document.getElementById('picks').appendChild(b);
    });

    function updateInfo() {
      document.getElementById('score').textContent = score;
      document.getElementById('lives').textContent = lives;
      document.getElementById('time').textContent = timeLeft;
    }

    function newWord() {
      const wordIndex = Math.floor(Math.random() * colors.length);
      inkIndex = Math.floor(Math.random() * colors.length);
      wordEl.textContent = colors[wordIndex].name;
      wordEl.style.color = colors[inkIndex].code;
    }

    function answer(i) {
      if (!running) return;
      if (i === inkIndex) {
        score += 1;
        msg.textContent = '⭕';
      } else {
        lives = Math.max(0, lives - 1);
        msg.textContent = '❌ 글자 색은 ' + colors[inkIndex].name + '였어요';
      }
      updateInfo();
      if (lives === 0) {
        endGame('💥 게임 오버! 점수: ' + score);
        return;
      }
      newWord();
    }

    function startGame() {
      clearInterval(timer);
      score = 0;
      lives = 3;
      timeLeft = 30;
      running = true;
      msg.textContent = '';
      document.getElementById('start').textContent = '다시 시작';
      updateInfo();
      newWord();
      timer = setInterval(function () {
        if (!running) return;
        timeLeft -= 1;
        updateInfo();
        if (timeLeft <= 0) endGame('⏰ 시간 끝! 점수: ' + score);
      }, 1000);
    }

    function endGame(text) {
      running = false;
      clearInterval(timer);
      timer = null;
      wordEl.textContent = '끝';
      wordEl.style.color = '#1f2937';
      msg.textContent = text;
    }

    document.getElementById('start').addEventListener('click', startGame);
  </script>
</body>
</html>
