    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
    ul { display: inline-block; text-align: left; }
  </style>
</head>
<body>
  <h1 id="title">🎯 Random picker</h1>
  <input id="nm" type="text" placeholder="Name">
  <button id="add">Add</button>
  <ul id="lst"></ul>
  <button id="pick">Pick one!</button>
  <h2 id="result"></h2>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var names, n;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    document.getElementById("add").addEventListener('click', function () {
      n = document.getElementById("nm").value.trim();
      if (!!n.length) {
        names.push(n);
        __add("lst", n);
        document.getElementById("nm").value = '';
      }
    });
    document.getElementById("pick").addEventListener('click', function () {
      if (!names.length) {
        document.getElementById("result").textContent = 'Add some names first';
      } else {
        document.getElementById("result").textContent = 'Picked: ' + String(listsGetRandomItem(names, false));
      }
    });

    names = [];
  </script>
</body>
</html>
