<body>
  <h2 id="title">발표자 뽑기</h2>
  <div id="in" class="box row">
    <input id="name" type="text" placeholder="이름">
    <button id="addBtn">추가</button>
  </div>
  <ul id="names"></ul>
  <button id="pick">뽑기</button>
  <h2 id="out"></h2>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var people;

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    document.getElementById("addBtn").addEventListener('click', function () {
      if (!!document.getElementById("name").value.trim().length) {
        people.push(document.getElementById("name").value.trim());
        __add("names", document.getElementById("name").value.trim());
        document.getElementById("name").value = '';
      }
    });
    document.getElementById("pick").addEventListener('click', function () {
      if (!people.length) {
        document.getElementById("out").textContent = '이름을 먼저 넣어 주세요';
      } else {
        document.getElementById("out").textContent = '오늘의 발표자: ' + String(listsGetRandomItem(people, false));
      }
    });

    people = [];
  </script>
</body>
